      path: "components/tilt-card/TiltCard.module.css",
      content: "/* ==========================================================================\n   3D parallax tilt card (Apple TV poster / holographic trading card)\n\n   root (perspective) → card (rotated by framer-motion, preserve-3d)\n     → content (preserve-3d) → TiltLayer × n (translateZ)\n     → holo foil (color-dodge, masked to the highlight)\n     → glare (radial highlight)\n\n   The card is NOT overflow: hidden — clipping flattens preserve-3d and the\n   layers would stop popping out. Each flat layer rounds its own corners.\n   ========================================================================== */\n\n.root {\n  /* Defaults. The component only sets these inline for non-default\n     values, so the default render is exactly this stylesheet. */\n  --tc-perspective: 1000px;\n  --tc-radius: 20px;\n\n  position: relative;\n  display: block;\n  perspective: var(--tc-perspective);\n  /* Leaves vertical page scroll to the browser on touch; pointer tracking\n     is mouse / pen only anyway. */\n  touch-action: pan-y;\n}\n\n.card {\n  position: relative;\n  width: 100%;\n  border-radius: var(--tc-radius);\n  transform-style: preserve-3d;\n  will-change: transform;\n}\n\n.content {\n  position: relative;\n  border-radius: inherit;\n  transform-style: preserve-3d;\n}\n\n.layer {\n  transform: translateZ(var(--tc-depth, 30px));\n  transform-style: preserve-3d;\n}\n\n/* Both overlays sit a hair above the surface (coplanar layers z-fight in\n   Safari) and below any TiltLayer, which reads like raised print. */\n.glare,\n.holo {\n  position: absolute;\n  inset: 0;\n  border-radius: inherit;\n  pointer-events: none;\n}\n\n.holo {\n  transform: translateZ(1px);\n  background-image:\n    repeating-linear-gradient(\n      115deg,\n      #ff77c8 0%,\n      #ffd36b 7%,\n      #75ffc6 14%,\n      #6fc6ff 21%,\n      #b28aff 28%,\n      #ff77c8 35%\n    ),\n    repeating-linear-gradient(\n      25deg,\n      rgba(255, 255, 255, 0.18) 0 1px,\n      transparent 1px 4px\n    );\n  background-size:\n    320% 320%,\n    100% 100%;\n  mix-blend-mode: color-dodge;\n  filter: saturate(1.15);\n}\n\n.glare {\n  transform: translateZ(2px);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .card {\n    will-change: auto;\n  }\n}\n",
