      path: "components/spinning-box/index.tsx",
      content: "\"use client\";\n\nimport { useRef } from \"react\";\nimport { useFrame } from \"@react-three/fiber\";\nimport type { Mesh } from \"three\";\n\nexport type SpinningBoxProps = {\n  color?: string;\n  /** Rotation speed multiplier. */\n  speed?: number;\n  wireframe?: boolean;\n  scale?: number;\n};\n\n/**\n * Scene content only — render inside a react-three-fiber <Canvas>.\n */\nexport function SpinningBox({\n  color = \"#8b5cf6\",\n  speed = 1,\n  wireframe = false,\n  scale = 1,\n}: SpinningBoxProps) {\n  const mesh = useRef<Mesh>(null);\n\n  useFrame((_, delta) => {\n    if (!mesh.current) return;\n    mesh.current.rotation.x += delta * speed * 0.6;\n    mesh.current.rotation.y += delta * speed;\n  });\n\n  return (\n    <mesh ref={mesh} scale={scale}>\n      <boxGeometry args={[1.6, 1.6, 1.6]} />\n      <meshStandardMaterial color={color} wireframe={wireframe} />\n    </mesh>\n  );\n}\n\nexport default SpinningBox;\n",
